{"script":"async () => {
  // Get the search results page information
  const articles = document.querySelectorAll('article');
  const results = [];
  articles.forEach((article, idx) => {
    const titleEl = article.querySelector('h2 a, h3 a, [data-testid="results-list"] h2 a');
    const starsEl = article.querySelector('[href*="/stargazers"]');
    const descEl = article.querySelector('p');
    if (titleEl) {
      results.push({
        index: idx,
        title: titleEl.textContent.trim(),
        stars: starsEl ? starsEl.textContent.trim() : 'N/A',
        description: descEl ? descEl.textContent.trim().substring(0, 200) : 'N/A'
      });
    }
  });
  return results;
}"}

