{"script":"() => {
  const articles = document.querySelectorAll('article.Box-row, [data-testid="repository"]');
  const items = [];
  // Try various selectors for the trending repos
  const allArticles = document.querySelectorAll('article');
  allArticles.forEach((article) => {
    const h2 = article.querySelector('h2');
    const desc = article.querySelector('p');
    const starsToday = Array.from(article.querySelectorAll('span')).find(s => s.textContent && s.textContent.includes('stars today'));
    const totalStars = article.querySelector('a[href*="/stargazers"]');
    items.push({
      title: h2 ? h2.textContent.trim() : 'NO H2',
      description: desc ? desc.textContent.trim().substring(0, 150) : 'NO DESC',
      totalStars: totalStars ? totalStars.textContent.trim() : 'NO TOTAL',
      starsToday: starsToday ? starsToday.textContent.trim() : 'NO TODAY'
    });
  });
  return items.slice(0, 15);
}"}

