{"script":"() => {
  // Find all elements that might contain topics
  const topicLinks = document.querySelectorAll('[href*="/topics/"]');
  const topics = [];
  topicLinks.forEach((el) => {
    const text = el.textContent.trim();
    if (text && !topics.includes(text)) {
      topics.push(text);
    }
  });
  return { topics: topics, count: topics.length };
}"}

